package hu.taliann.icesmp.playerprofile.http;
import java.lang.reflect.*;import java.time.*;import java.util.*;
public final class PlayerProfileJson {private PlayerProfileJson(){}
 public static String encode(Object value){StringBuilder b=new StringBuilder();write(b,value);return b.toString();}
 private static void write(StringBuilder b,Object v){if(v==null){b.append("null");return;}if(v instanceof String||v instanceof Character||v instanceof UUID||v instanceof Instant||v instanceof Enum<?>){quote(b,v instanceof Enum<?> e?e.name().toLowerCase(Locale.ROOT):v.toString());return;}if(v instanceof Boolean||v instanceof Number){b.append(v);return;}if(v instanceof Map<?,?> m){b.append('{');boolean first=true;for(var e:m.entrySet()){if(!first)b.append(',');first=false;quote(b,String.valueOf(e.getKey()));b.append(':');write(b,e.getValue());}b.append('}');return;}if(v instanceof Iterable<?> i){b.append('[');boolean first=true;for(Object x:i){if(!first)b.append(',');first=false;write(b,x);}b.append(']');return;}if(v.getClass().isArray()){b.append('[');for(int i=0;i<Array.getLength(v);i++){if(i>0)b.append(',');write(b,Array.get(v,i));}b.append(']');return;}if(v.getClass().isRecord()){b.append('{');boolean first=true;for(RecordComponent c:v.getClass().getRecordComponents()){if(!first)b.append(',');first=false;quote(b,kebab(c.getName()));b.append(':');try{write(b,c.getAccessor().invoke(v));}catch(ReflectiveOperationException e){throw new IllegalStateException("DTO serialization failed");}}b.append('}');return;}throw new IllegalArgumentException("unsupported JSON DTO type");}
 private static String kebab(String s){return s.replaceAll("([a-z0-9])([A-Z])","$1-$2").toLowerCase(Locale.ROOT);}private static void quote(StringBuilder b,String s){b.append('"');for(char c:s.toCharArray()){switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<0x20)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}}b.append('"');}
}
